import { stat } from "node:fs/promises";
import path from "node:path";
import { collectImageReferences } from "./image-usage.mjs";

// These paths are generated by Astro rather than committed to public/.
const generatedImageRoute = /^\/(?:og-image\.(?:png|svg)|og\/.+\.(?:png|svg))$/i;

export function resolveDocumentImage(reference, markdownFile, repositoryRoot) {
  if (!reference || /^(?:[a-z][\w+.-]*:|\/\/|#)/i.test(reference)) return null;
  let raw;
  try {
    raw = decodeURIComponent(reference.split(/[?#]/)[0]);
  } catch {
    throw new Error("Invalid image URL encoding: " + reference);
  }
  if (!raw) return null;
  if (generatedImageRoute.test(raw)) return null;

  const destination = raw.startsWith("/")
    ? path.resolve(repositoryRoot, "public", raw.slice(1))
    : path.resolve(path.dirname(markdownFile), raw);
  const relative = path.relative(path.resolve(repositoryRoot), destination);
  if (!relative || relative === ".." || relative.startsWith(".." + path.sep) || path.isAbsolute(relative)) {
    throw new Error("Image path escapes repository: " + reference);
  }
  return destination;
}

export async function inspectDocumentImages(source, markdownFile, repositoryRoot) {
  // Hidden README examples must not be treated as rendered images.
  const visible = source.replace(/<!--[\s\S]*?-->/g, "");
  const resolved = new Set();
  const errors = [];

  for (const reference of collectImageReferences(visible)) {
    let image;
    try {
      image = resolveDocumentImage(reference, markdownFile, repositoryRoot);
    } catch (error) {
      errors.push(error.message);
      continue;
    }
    if (!image) continue;
    resolved.add(image);
    try {
      const item = await stat(image);
      if (!item.isFile()) errors.push("Image path is not a file: " + reference);
    } catch {
      errors.push("Missing local image: " + reference);
    }
  }

  return { referenced: [...resolved], errors };
}
